package org.acme.model;

import jakarta.persistence.*;
import org.hibernate.annotations.UuidGenerator;
import java.time.LocalDate;
import java.util.UUID;

/** A percentage-based assignment of an employee to a project over a date range. */
@Entity
@Table(name = "tb_allocation", schema = "talent")
public class Allocation {

    /** Creates an empty allocation entity. */
    public Allocation() {
    }

    /** Allocation identifier generated by Hibernate. */
    @Id
    @UuidGenerator(style = UuidGenerator.Style.TIME)
    @Column(name = "id", updatable = false, nullable = false)
    public UUID id;

    /** Employee assigned to the project. */
    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "employee_id", nullable = false)
    public Employee employee;

    /** Project to which the employee is assigned. */
    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "project_id", nullable = false)
    public Project project;

    /** Percentage of the employee's capacity allocated to the project. */
    @Column(name = "allocation_percentage", nullable = false)
    public Integer allocationPercentage;

    /** First date of the allocation. */
    @Column(name = "start_date", nullable = false)
    public LocalDate startDate;

    /** Last date of the allocation, or {@code null} when no end date is set. */
    @Column(name = "end_date")
    public LocalDate endDate;
}
